import{_ as r,c as a,o as s,ae as i}from"./chunks/framework.CHDT0Kbg.js";const p=JSON.parse('{"title":"Choix de confidentialité","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/privacy-choices.md","filePath":"fr/guide/privacy-choices.md","lastUpdated":1795170900000}'),t={name:"fr/guide/privacy-choices.md"};function n(o,e,c,l,u,d){return s(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="choix-de-confidentialite" tabindex="-1">Choix de confidentialité <a class="header-anchor" href="#choix-de-confidentialite" aria-label="Permalink to &quot;Choix de confidentialité&quot;">​</a></h1><p>Des moyens simples de garder le contrôle.</p><h2 id="naviguer-sans-traces" tabindex="-1">Naviguer sans traces <a class="header-anchor" href="#naviguer-sans-traces" aria-label="Permalink to &quot;Naviguer sans traces&quot;">​</a></h2><p>Utilisez une fenêtre privée (⌘⇧N). Elle n&#39;écrit rien dans l&#39;historique, ne mémorise pas la session, et ses onglets disparaissent à la fermeture.</p><h2 id="effacer-ce-qui-est-enregistre" tabindex="-1">Effacer ce qui est enregistré <a class="header-anchor" href="#effacer-ce-qui-est-enregistre" aria-label="Permalink to &quot;Effacer ce qui est enregistré&quot;">​</a></h2><p>Supprimez les cookies et les données de sites depuis le gestionnaire de cookies des réglages. L&#39;historique et les téléchargements peuvent aussi être effacés au même endroit.</p><h2 id="decider-ce-que-chaque-site-peut-faire" tabindex="-1">Décider ce que chaque site peut faire <a class="header-anchor" href="#decider-ce-que-chaque-site-peut-faire" aria-label="Permalink to &quot;Décider ce que chaque site peut faire&quot;">​</a></h2><p>Caméra, micro et accès aux fichiers sont mémorisés par site. Autorisez les sites de confiance et refusez les autres dans les réglages. Les fenêtres surgissantes ne s&#39;ouvrent que sur les sites autorisés.</p><h2 id="controler-les-fonctions-en-arriere-plan" tabindex="-1">Contrôler les fonctions en arrière-plan <a class="header-anchor" href="#controler-les-fonctions-en-arriere-plan" aria-label="Permalink to &quot;Contrôler les fonctions en arrière-plan&quot;">​</a></h2><p>Activez ou désactivez les abonnements de filtrage à tout moment depuis les réglages. Désactivé, aucun filtre n&#39;est téléchargé.</p><h2 id="choisir-votre-moteur-de-recherche" tabindex="-1">Choisir votre moteur de recherche <a class="header-anchor" href="#choisir-votre-moteur-de-recherche" aria-label="Permalink to &quot;Choisir votre moteur de recherche&quot;">​</a></h2><p>Définissez votre moteur par défaut dans les réglages. Les suggestions proviennent du moteur choisi.</p><h2 id="une-question" tabindex="-1">Une question <a class="header-anchor" href="#une-question" aria-label="Permalink to &quot;Une question&quot;">​</a></h2><p>Écrivez à <strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong> pour en savoir plus sur le traitement de vos données.</p>',14)])])}const f=r(t,[["render",n]]);export{p as __pageData,f as default};
